def finding(row):
    fid,name,desc,kind,refs,vkind,required=row
    return {"id":fid,"name":name,"description":desc,"source_refs":refs,"questions":[
        {"id":fid+"-q01","text":f"What exact identities, classes, values, links and explicit unknowns define {name.lower()} for this authorization case?","kind":kind,"answer_data":["identities and values","class and profile","links","unknowns"]},
        {"id":fid+"-q02","text":f"Which competent actor, legal source, submission, evidence, decision and event or knowledge time supports {name.lower()}?","kind":"evidence","answer_data":["actor and competence","legal source","submission or evidence","decision","times"]},
        {"id":fid+"-q03","text":f"How may {name.lower()} be validated, contested, corrected, superseded, retained or disclosed without implying an external grant or erasing history?","kind":"validation","answer_data":["validation","contest route","grant non-inference","successor","retention and access"]}],
        "data_elements":[{"id":fid+"-data","name":name+" data","description":"Structured authority-qualified case data for "+name.lower()+".","value_kind":vkind,"cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
        "artifacts":[{"id":fid+"-record","name":name+" record","description":"Versioned evidence-bearing case record for "+name.lower()+" with legal basis, event and knowledge time, provenance and access marking.","media_or_form":["logical authorization-case record","authoritative decision or evidence reference"],"serial":True,"identity_strategy":"Authorization-case identifier plus "+fid+" assertion or event identifier; applicant, permit number, title, date and hash never identify the case alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    return {"bundles":[{"id":bid,"name":name,"description":desc,"rationale":why,"source_refs":refs,"layers":[{"id":lid,"name":lname,"description":ldesc,"source_refs":lrefs,"findings":[finding(x) for x in findings]} for lid,lname,ldesc,lrefs,findings in layers]} for bid,name,desc,why,refs,layers in BUNDLES]}

